import pathlib,json
BASE=pathlib.Path(__file__).resolve().parent;OUT=BASE.parent/'outputs'
data=json.loads((BASE/'catalogue_data.json').read_text(encoding='utf-8'))
payload=json.dumps(data,ensure_ascii=False,separators=(',',':')).replace('</','<'+chr(92)+'/')
template=r'''<!DOCTYPE html>
<html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>我的 AI 开发程序目录</title>
<style>
:root{color-scheme:light;--ink:#19283a;--muted:#607183;--line:#dbe4ea;--nav:#172d46;--accent:#166d89}*{box-sizing:border-box}body{margin:0;background:#f2f5f8;color:var(--ink);font:15px/1.6 "Microsoft YaHei",system-ui,sans-serif}header{background:var(--nav);color:#fff;padding:28px max(24px,4vw)}header h1{margin:0;font-size:28px;font-weight:650}header p{color:#c3d5e5;margin:8px 0 0;max-width:1000px}.wrap{max-width:1620px;margin:24px auto;padding:0 24px}.stats{display:grid;grid-template-columns:repeat(5,1fr);gap:14px}.stat{padding:16px 20px;background:#fff;border:1px solid var(--line);border-radius:10px}.stat strong{display:block;font-size:26px;color:var(--accent)}.stat small{color:var(--muted);font-size:14px}.notice{background:#fff6df;border:1px solid #efd497;padding:14px 18px;border-radius:8px;margin:20px 0;font-size:14px}.tabs{display:flex;flex-wrap:wrap;gap:6px;border-bottom:1px solid var(--line);padding-bottom:10px}.tabs button{border:0;border-radius:6px;padding:11px 18px;background:transparent;cursor:pointer;font:inherit}.tabs button.active{background:var(--nav);color:white}.toolbar{display:flex;gap:10px;flex-wrap:wrap;align-items:center;margin:18px 0}input,select{font:inherit;padding:10px 12px;border:1px solid #bbcbd7;border-radius:6px;background:white}#search{flex:1;min-width:250px}.toolbar .hint{font-size:13px;color:var(--muted)}.tablewrap{background:#fff;border:1px solid var(--line);border-radius:9px;overflow:auto}table{width:100%;border-collapse:collapse;table-layout:fixed;min-width:1000px}th{background:#e8eff5;padding:12px;text-align:left;color:#24435e;font-size:13px}td{padding:13px 12px;border-top:1px solid #e7edf1;vertical-align:top;overflow-wrap:anywhere;font-size:14px}tr:hover td{background:#f8fafc}td .name{font-weight:650;color:#173d5b}td .sub{display:block;font-size:12px;color:var(--muted);margin-top:5px}.badge{display:inline-block;border-radius:4px;font-size:12px;padding:3px 8px;background:#e8f1f5;color:#285b70}.badge.warn{background:#fff0d8;color:#865310}.badge.good{background:#e1f3eb;color:#26704f}button.detail{background:#fff;border:1px solid #b8cbd7;color:#255e76;padding:6px 12px;border-radius:5px;cursor:pointer}a{color:#146f95}.pager{display:flex;justify-content:space-between;align-items:center;padding:16px 0;color:var(--muted)}.pager button{padding:8px 14px;border:1px solid var(--line);background:#fff;border-radius:5px;margin-left:5px;cursor:pointer}footer{padding:20px 0 40px;color:var(--muted);font-size:13px}.modal{position:fixed;inset:0;background:#0b1c2cb8;display:none;justify-content:center;align-items:flex-start;overflow:auto;padding:35px 16px;z-index:5}.modal.open{display:flex}.panel{width:920px;max-width:100%;background:#fff;border-radius:12px;padding:28px;box-shadow:0 20px 80px #0004}.panel h2{margin:0 0 4px;font-size:22px}.panel .close{float:right;border:0;border-radius:5px;background:#e7edf3;padding:8px 14px;cursor:pointer}.field{margin-top:18px}.field label{font-size:13px;color:var(--muted);display:block;margin-bottom:4px}.field p{white-space:pre-wrap;margin:0}.path{font:13px/1.7 Consolas,monospace;background:#f0f4f7;padding:10px;border-radius:5px;word-break:break-all}.actions{margin-top:10px;display:flex;gap:12px;align-items:center}.note{color:var(--muted);font-size:13px}.video{font-size:13px;width:100%;padding:6px}.empty{text-align:center;padding:40px}.links{display:flex;gap:16px;flex-wrap:wrap}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}.wrap{padding:0 14px}header{padding:22px}.panel{padding:20px}}
</style></head><body>
<header><h1>我的 AI 开发程序目录</h1><p>把散落在电脑中的程序、源码、历史版本与启动入口连起来。名称、用途、使用方式、路径和后续演示计划统一查找。</p></header>
<main class="wrap"><div class="stats" id="stats"></div><div class="notice"><strong>时间与归属说明：</strong>开发顺序是依据目录日期、Git和文件时间推定的；“开发候选”不能证明全部为AI生成。源码检查通过也不等于完整功能验收。系统、依赖和收到的软件分别标注，扫描范围见下方说明。</div>
<nav class="tabs" id="tabs"></nav><div class="toolbar"><input id="search" placeholder="搜索名称、用途、文件或路径…" aria-label="搜索目录"><select id="category" aria-label="分类"><option value="">全部分类</option></select><select id="scopeFilter" aria-label="文件范围"><option value="">全部文件类别</option><option>开发候选</option><option>收到或下载的程序，作者待核实</option><option>运行环境或依赖组件</option><option>第三方软件或安装组件</option><option>AI开发过程辅助文件</option></select><span class="hint" id="resultCount"></span></div>
<div class="tablewrap"><table><thead id="thead"></thead><tbody id="tbody"></tbody></table></div><div class="pager"><span id="pageLabel"></span><div><button id="prev">上一页</button><button id="next">下一页</button></div></div>
<footer><div class="links"><a href="程序清单/AI开发程序总清单.xlsx">打开 Excel 总清单</a><a href="整理说明与开发顺序.md">整理说明与开发顺序</a><a href="全部文件索引.json">完整文件索引</a></div><p id="scopeNote"></p><p>录制状态保存在当前浏览器的本地存储中；更换浏览器不会自动同步。表内路径指向原文件，点击链接会由本机浏览器处理。本次仅修复已列出的源码，没有搬动原项目目录。</p></footer></main>
<div class="modal" id="modal" role="dialog" aria-modal="true" aria-label="程序详情"><article class="panel"><button class="close" id="close">关闭</button><h2 id="detailTitle"></h2><div id="detailBody"></div></article></div>
<script id="catalogue-data" type="application/json">PAYLOAD</script><script>
'use strict';
const data=JSON.parse(document.getElementById('catalogue-data').textContent);const $=id=>document.getElementById(id);
const text=(tag,value,cls)=>{const e=document.createElement(tag);e.textContent=value??'';if(cls)e.className=cls;return e};
const tabs=[['projects','项目目录'],['programs','程序入口'],['video','使用视频计划'],['issues','问题与修复'],['tools','开发工具'],['files','全部文件索引']];
let view='projects',page=0,filtered=[],size=25;
const stats=[['项目/目录候选',data.counts.projects],['程序与脚本入口',data.counts.program_entries],['扫描记录',data.counts.scan_records],['已修复文件',data.counts.repaired_files],['仍有Python语法错误',data.counts.remaining_python_syntax_errors]];
for(const [label,value] of stats){const e=text('div','', 'stat');e.append(text('strong',value),text('small',label));$('stats').append(e)}
for(const [key,label] of tabs){const b=text('button',label);b.dataset.view=key;b.onclick=()=>{view=key;page=0;setupFilters();render()};$('tabs').append(b)}
const categories=[...new Set(data.projects.map(x=>x.category))].sort();for(const c of categories){const o=text('option',c);o.value=c;$('category').append(o)}
function setupFilters(){$('category').style.display=['projects','programs','video'].includes(view)?'':'none';$('scopeFilter').style.display=view==='files'?'':'none';$('search').value='';$('category').value='';$('scopeFilter').value='';for(const b of $('tabs').children)b.classList.toggle('active',b.dataset.view===view)}
function statusBadge(value){return text('span',value,'badge '+(/错误|异常|缺失|未修复|未核实/.test(value)?'warn':/本次已修复|已写回/.test(value)?'good':''))}
function openLink(path,label){const a=text('a',label);a.href='file:///'+path.split(String.fromCharCode(92)).join('/').split('/').map((v,i)=>i===0?v:encodeURIComponent(v)).join('/');a.target='_blank';a.rel='noopener';return a}
function videoStatus(r){try{return localStorage.getItem('ai-video:'+r.path)||'待录制'}catch{return '待录制'}}
function makeVideoControl(r){const s=document.createElement('select');s.className='video';s.setAttribute('aria-label',r.name+'录制状态');for(const v of ['待录制','待修复/验收','录制中','已完成']){const o=text('option',v);o.value=v;s.append(o)}s.value=videoStatus(r);s.onchange=()=>{try{localStorage.setItem('ai-video:'+r.path,s.value)}catch{alert('当前浏览器无法保存录制状态，请使用Excel记录。')}};return s}
function getRows(){return view==='video'?data.programs:data[view]}
function render(){const query=$('search').value.trim().toLowerCase(),cat=$('category').value,scope=$('scopeFilter').value;filtered=getRows().filter(r=>(!query||JSON.stringify(r).toLowerCase().includes(query))&&(!['projects','programs','video'].includes(view)||!cat||r.category===cat)&&(view!=='files'||!scope||r.category===scope));page=Math.min(page,Math.max(0,Math.ceil(filtered.length/size)-1));$('tbody').replaceChildren();$('thead').replaceChildren();
let headers,widths;if(view==='projects'){headers=['顺序 / 时间','项目与用途','使用与状态','路径 / 工具','详情'];widths=['12%','27%','29%','24%','8%']}else if(view==='programs'){headers=['顺序 / 时间','程序与类型','使用 / 当前检查','原路径 / 重复副本','详情'];widths=['12%','25%','30%','25%','8%']}else if(view==='video'){headers=['程序','演示流程','录制准备','状态','详情'];widths=['24%','32%','24%','12%','8%']}else if(view==='issues'){headers=['问题类型','文件 / 问题','处理与验证','当前状态','详情'];widths=['13%','33%','30%','16%','8%']}else if(view==='tools'){headers=['工具','路径','用途','入口状态','详情'];widths=['19%','35%','28%','10%','8%']}else{headers=['文件名 / 类型','归类','原路径','时间 / 大小','详情'];widths=['20%','20%','34%','18%','8%']}
const tr=document.createElement('tr');headers.forEach((h,i)=>{const th=text('th',h);th.style.width=widths[i];tr.append(th)});$('thead').append(tr);
for(const r of filtered.slice(page*size,(page+1)*size)){const row=document.createElement('tr');const cells=Array.from({length:5},()=>document.createElement('td'));const add=(i,v,cls)=>cells[i].append(text('div',v,cls));
if(view==='projects'){add(0,r.order+' · '+r.id);add(0,r.date||'日期待核实','sub');add(0,r.date_basis,'sub');add(1,r.name,'name');add(1,r.purpose);add(1,r.category,'sub');add(2,r.usage);cells[2].append(statusBadge(r.status));add(3,r.path,'sub');add(3,r.tool);add(3,r.files+'份代码/程序记录 · '+r.types,'sub')}
else if(view==='programs'){add(0,r.order+' · '+r.id);add(0,r.date,'sub');add(1,r.name,'name');add(1,r.type,'sub');add(1,r.project_name,'sub');add(2,r.usage);cells[2].append(statusBadge(r.status));add(3,r.path,'sub');if(r.duplicate_paths.length)add(3,'另有 '+r.duplicate_paths.length+'份完全相同文本副本','sub')}
else if(view==='video'){add(0,r.name,'name');add(0,r.id+' · '+r.type,'sub');add(1,r.demo);add(1,'建议2–4分钟：用途 → 启动 → 完整示例 → 结果与限制','sub');add(2,/脚本/.test(r.type)?'辅助或维护脚本先审查，通常可并入项目演示。':'使用示例文件与虚构资料；先完成启动与功能验收。');add(2,r.status,'sub');cells[3].append(makeVideoControl(r))}
else if(view==='issues'){cells[0].append(statusBadge(r.kind));add(1,r.path,'sub');add(1,r.problem);add(2,r.action);add(3,r.status)}
else if(view==='tools'){add(0,r.name,'name');add(1,r.path,'sub');add(2,r.purpose);add(3,r.status)}
else{add(0,r.name,'name');add(0,r.extension,'sub');add(1,r.category);add(2,r.path,'sub');add(3,'创建 '+String(r.created).slice(0,10),'sub');add(3,'修改 '+String(r.modified).slice(0,10),'sub');add(3,Number.isFinite(r.size)?(r.size/1024).toFixed(1)+' KB':'未取得大小','sub');if(r.syntax)add(3,r.syntax,'sub')}
const b=text('button','查看','detail');b.onclick=()=>showDetail(r);cells[4].append(b);cells.forEach(c=>row.append(c));$('tbody').append(row)}
if(!filtered.length){const row=document.createElement('tr'),cell=text('td','没有匹配结果','empty');cell.colSpan=5;row.append(cell);$('tbody').append(row)}$('resultCount').textContent='共 '+filtered.length+' 条';$('pageLabel').textContent='第 '+(page+1)+' / '+Math.max(1,Math.ceil(filtered.length/size))+' 页';$('prev').disabled=page===0;$('next').disabled=(page+1)*size>=filtered.length;}
function showDetail(r){$('detailTitle').textContent=r.name||r.kind||r.path;$('detailBody').replaceChildren();const labels={date:'推定时间',date_basis:'时间依据',purpose:'用途',role:'作用',features:'源码显示的入口',usage:'使用方式',path:'原路径',entry:'优先核对的启动入口',tool:'开发工具证据',ai_evidence:'AI来源说明',status:'检查状态',demo:'演示视频提纲',problem:'具体问题',action:'处理与验证',backup:'原版备份',repaired_copy:'修复版本',project_name:'所属项目',created:'创建时间',modified:'修改时间',read_error:'读取异常',git_date:'仓库最早提交'};
for(const [k,label] of Object.entries(labels)){if(!r[k])continue;const f=text('div','', 'field');f.append(text('label',label),text('p',r[k],['path','entry','backup','repaired_copy'].includes(k)?'path':''));if(['path','entry','backup','repaired_copy'].includes(k)){const acts=text('div','', 'actions'),b=text('button','复制路径','detail');b.onclick=async()=>{try{await navigator.clipboard.writeText(r[k]);b.textContent='已复制'}catch{const t=document.createElement('textarea');t.value=r[k];document.body.append(t);t.select();document.execCommand('copy');t.remove();b.textContent='已复制'}};acts.append(b,openLink(r[k],'打开原文件或目录'));f.append(acts)}$('detailBody').append(f)}
if(r.duplicate_paths?.length){const f=text('div','', 'field');f.append(text('label','内容完全一致的其他文本副本'));for(const p of r.duplicate_paths)f.append(text('p',p,'path'));$('detailBody').append(f)}$('modal').classList.add('open')}
$('search').oninput=()=>{page=0;render()};$('category').onchange=$('scopeFilter').onchange=()=>{page=0;render()};$('prev').onclick=()=>{page--;render()};$('next').onclick=()=>{page++;render()};$('close').onclick=()=> $('modal').classList.remove('open');$('modal').onclick=e=>{if(e.target===$('modal'))$('modal').classList.remove('open')};document.addEventListener('keydown',e=>{if(e.key==='Escape')$('modal').classList.remove('open')});$('scopeNote').textContent='截至 '+data.as_of+'。'+data.scope.limits;setupFilters();render();
</script></body></html>'''
(OUT/'AI开发程序目录.html').write_text(template.replace('PAYLOAD',payload),encoding='utf-8')
print('HTML目录已生成')
